// Decide where each new article can go, using Ampost's own platform rules.
const rules = $('Get platform rules').first().json.data;
const settings = $('Settings').all();
const pages = $('Get article page').all();

return settings.map((setting, i) => {
  const a = setting.json;
  const html = String(pages[i]?.json?.data ?? '');
  const og =
    html.match(/<meta[^>]+property=["']og:image["'][^>]+content=["']([^"']+)["']/i) ||
    html.match(/<meta[^>]+content=["']([^"']+)["'][^>]+property=["']og:image["']/i);
  const image = og?.[1] || a.enclosure?.url || '';
  const articleText = String(a['content:encoded'] || a.content || a.contentSnippet || '')
    .replace(/<[^>]+>/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, 6000);

  const targets = [];
  const skipped = [];
  const wanted = String(a.platforms).split(',').map((p) => p.trim().toLowerCase()).filter(Boolean);
  for (const platform of wanted) {
    const rule = rules.find((r) => r.platform === platform);
    if (!rule) {
      skipped.push({ platform, reason: 'Ampost has no platform with this name' });
    } else if (rule.availability !== 'available') {
      skipped.push({ platform, reason: 'not available in Ampost yet' });
    } else if (rule.media.required && !(image && rule.media.types.includes('image'))) {
      const reason = rule.media.types.includes('image')
        ? 'needs an image, and the article has none'
        : 'needs a video';
      skipped.push({ platform, reason });
    } else {
      targets.push({ platform, maxLength: rule.text.maxLength, linkSupported: rule.link.supported });
    }
  }

  return {
    json: {
      title: a.title,
      link: a.link,
      articleText,
      image,
      brandVoice: a.brandVoice,
      whenToPost: a.whenToPost,
      reportEmail: a.reportEmail,
      targets,
      skipped,
    },
    pairedItem: { item: i },
  };
});

parameters.text:
=Write one social media post per platform to promote this blog article.

Title: {{ $json.title }}
Article: {{ $json.articleText }}

Voice: {{ $json.brandVoice }}

Platforms, with the length to aim for and the hard limit for each:
{{ $json.targets.map(t => '- ' + t.platform + ': about ' + Math.min(Math.floor(t.maxLength * 0.8), 600) + ' characters, never more than ' + t.maxLength + (t.linkSupported ? '' : ' (links are not clickable there, so end with "Link in bio.")')).join('\n') }}

Rules:
- Write each post for that platform's audience. Don't post the same text everywhere.
- Count characters. A post over its hard limit gets cut.
- One idea per post, in plain words. Skip lists of every detail; the article has them.
- Don't include the article URL: it is attached to the post.
- Lead with the most useful idea from the article, not with "New blog post".
- Write in the article's language.

