// One Ampost post with a text per platform. Ampost checks the limits again in the next step.
const plan = $('Plan platforms').item.json;
const written = $json.output?.posts ?? [];
const skipped = [...plan.skipped];
const options = {};

for (const target of plan.targets) {
  let text = written.find((p) => String(p.platform).toLowerCase() === target.platform)?.text?.trim();
  if (!text) {
    skipped.push({ platform: target.platform, reason: 'the AI wrote no text for it' });
    continue;
  }
  const chars = [...text];
  if (chars.length > target.maxLength) {
    // Cut at the last space that fits and add an ellipsis.
    const cut = chars.slice(0, target.maxLength - 1).join('');
    text = cut.slice(0, Math.max(cut.lastIndexOf(' '), 1)).trimEnd() + '…';
  }
  options[target.platform] = { text };
}

const platforms = Object.keys(options);
const body = {
  targets: [{ platforms }],
  text: platforms.length ? options[platforms[0]].text : plan.title,
  linkUrl: plan.link,
  options,
  metadata: { source: 'n8n blog template', article: plan.link },
};
if (plan.image) body.media = [{ url: plan.image, type: 'image' }];
if (plan.whenToPost === 'queue') body.useQueue = true;

return { json: { body, skipped } };

// Keep the platforms Ampost accepted and note why the others were left out.
const check = $json;
const built = $('Build the post').item.json;
const skipped = [...built.skipped];
const notes = [];
const accepted = [];

const plain = (e) =>
  e.code === 'PLATFORM_NOT_CONNECTED' ? 'no connected account in Ampost' : e.message;
for (const target of check.targets ?? []) {
  if (target.valid) accepted.push(target.platform);
  else skipped.push({ platform: target.platform, reason: target.errors.map(plain).join('; ') });
}

const body = JSON.parse(JSON.stringify(built.body));
body.targets = [{ platforms: accepted }];
for (const platform of Object.keys(body.options)) {
  if (!accepted.includes(platform)) delete body.options[platform];
}
if (accepted.length) body.text = body.options[accepted[0]].text;

const general = check.errors ?? [];
if (general.some((e) => e.code === 'QUEUE_EMPTY')) {
  delete body.useQueue;
  notes.push('Your Ampost queue has no time slots, so the post was saved as a draft. Add slots under Queue in Ampost.');
}
const blocking = general.filter((e) => e.code !== 'QUEUE_EMPTY').map((e) => e.message);

return { json: { body, platforms: accepted, skipped, notes, blocking } };

// One short report per article, whichever way the run went.
const from = (name) => {
  try {
    return $(name).item.json;
  } catch {
    return null;
  }
};
const plan = from('Plan platforms') ?? {};
const sorted = from('Sort the check result');
const built = from('Build the post');
const skipped = sorted?.skipped ?? built?.skipped ?? plan.skipped ?? [];
const notes = [...(sorted?.notes ?? [])];
const lines = [];
let outcome;

if ($json.id && $json.status) {
  const when = $json.scheduledFor ? 'scheduled for ' + $json.scheduledFor : $json.status;
  outcome = 'Added to Ampost for ' + sorted.platforms.join(', ') + ' (' + when + ')';
  lines.push(outcome + '.', 'Post ID: ' + $json.id);
} else if ($json.error) {
  outcome = 'Failed';
  lines.push('The run failed: ' + (typeof $json.error === 'string' ? $json.error : JSON.stringify($json.error)));
} else if (sorted?.blocking?.length) {
  outcome = 'Not posted';
  lines.push('Ampost refused the post: ' + sorted.blocking.join('; '));
} else {
  outcome = 'Not posted';
  lines.push('No platform could take this article.');
}

if (skipped.length) {
  lines.push('', 'Left out:');
  for (const s of skipped) lines.push('- ' + s.platform + ': ' + s.reason);
}
if (notes.length) lines.push('', ...notes);
lines.push('', 'Article: ' + (plan.link ?? ''));

return {
  json: {
    to: plan.reportEmail,
    subject: outcome + ': ' + (plan.title ?? 'blog article'),
    text: lines.join('\n'),
  },
};
